test('at its document\'s head the face stands compact in the rows — its compact form an act naming its hand — the band its fold reserves holding its row; its act opens the corner whole, the face whole beneath the rows with its acts, and a press answered at it opens it so too, its words said (issue #598; B3-S2; FP-26; D6 BM-45)', () => onHead(({ said }) => {
  REC.setSession(/** @type {any} */ ({ session: 's-1', principal: 1, account: '1.0.1', writes: true }));
  LAYER.readers({ top: () => LINE_PX, face: FACES.cornerFace });
  CAM.setViewport(390, 900);
  landAt(null);
  LAYER.frame();
  const bare = LAYER.foldOf(REC.doc(D)).band;
  WRITE.setHeld(D, /** @type {any} */ (F.decodeHeldRows([{ held: 1, doc: D, base: 7, frame: { op: 'insert', doc: D, at: { ordinal: '1', subspace: '1' }, values: ['held'], as_of: 7, id: 'p.1' }, cause: 'moved', sent: true, time: 1, refusal: { kind: 'refused', name: 'arrangement_moved', status: 200, code: 'arrangement_moved', detail: null, op: 'insert', site: { as_of: 7, current: 9 }, body: null }, sendable: false, hands: [{ key: 'other', fingerprint: 'ab'.repeat(32), label: 'desk' }] }])));
  WRITE.setKept(D, { word: 'not yet kept', reason: null, cause: { token: 'moved', arm: null } });
  LAYER.frame();
  const el = /** @type {any} */ (LAYER.cornerOf(D)), rows = () => String(el.innerHTML).split('<div class="opened"')[0];
  assert.ok(LAYER.cornerAt(D)?.head && LAYER.foldOf(REC.doc(D)).band > bare, `the corner at its head, its band deeper for the face's row: ${bare} → ${LAYER.foldOf(REC.doc(D)).band}`);
  assert.ok(rows().includes(`data-face="whole" data-whole data-string="B3.moved.compact" aria-expanded="false"`) && rows().includes(esc(t('B3.moved.compact', { hand: 'desk' }))) && !rows().includes('data-face="discard"'), `in the rows its compact form, its acts one act away — ${rows()}`);
  LAYER.openCorner(D);
  LAYER.frame();
  const opened = String(el.innerHTML).split('<div class="opened"')[1] || '';
  assert.ok(opened.includes('<span class="face">') && opened.includes('data-face="discard"') && opened.includes('data-face="held"') && rows().includes('aria-expanded="true"'), `opened: the face whole beneath the rows, with its acts — ${opened}`);
  LAYER.openCorner(D);
  LAYER.frame();
  const n = said.length;
  assert.deepEqual([FACES.answerAtFace(D), LAYER.cornerAt(D)?.opened], [true, true], 'a press answered at the face: the corner opened whole');
  assert.deepEqual(said.slice(n), [heard(faceRuns(/** @type {any} */ (FACES.cornerFace(D))))], 'its words said, as a screen reader hears them');
  assert.deepEqual([FACES.answerAtFace(D), LAYER.cornerAt(D)?.opened], [true, true], 'pressed again: it stays opened');
}));

test('a draft\'s kept line, its second act offered, stands on two rows in a corner beside its column — the word alone, the act on a row of its own beneath it — and on one row at its document\'s head — the word\'s slot, the joiner, the act — the plane\'s corner and a reading scene\'s pane\'s alike (issue #694; FP-26)', () => onHead(() => {
  const was = { session: REC.session(), kept: WRITE.keptOf(D) };
  REC.setSession(/** @type {any} */ ({ session: 's-1', principal: 1, account: '1.0.1', writes: true }));
  try {
    WRITE.setKept(D, { word: 'kept', reason: null });
    assert.ok(LAYER.historyAct(D), 'a draft the person may edit: its kept line offers its second act');
    landAt(null);
    LAYER.frame();
    const beside = String(/** @type {any} */ (LAYER.cornerOf(D)).innerHTML);
    assert.ok(LAYER.cornerAt(D)?.head === false && beside.includes('<span class="kept-act"><button type="button" class="history" data-history') && !beside.includes('kept-slot'), `1440 px, the plane's corner beside its column: the act on a row of its own, no slot — ${beside}`);
    CAM.setViewport(390, 900);
    landAt(null);
    LAYER.frame();
    const head = String(/** @type {any} */ (LAYER.cornerOf(D)).innerHTML);
    assert.ok(LAYER.cornerAt(D)?.head && head.includes('class="kept-slot"') && head.includes('data-history') && !head.includes('kept-act'), `390 px, at its document's head: the word's slot, the joiner and the act on one row — ${head}`);
    const d = REC.doc(D), view = { ...LAYER.sceneView(d), kept: /** @type {const} */ ({ word: 'kept', reason: null }), history: { inert: null } };
    for (const compact of [false, true]) {
      const pane = LAYER.sceneCorner(d, view, compact);
      assert.ok(pane.includes('<span class="kept-act"><button type="button" class="history" data-history') && !pane.includes('kept-slot'), `a pane's corner beside its column, ${compact ? 'compact' : 'whole'}: the act on a row of its own, no slot — ${pane}`);
    }
    const paneHead = LAYER.sceneHead(d, view, { px: 17, kept: null, open: false }).html;
    assert.ok(paneHead.includes('class="kept-slot"') && paneHead.includes('data-history') && !paneHead.includes('kept-act'), `a pane's corner at its document's head: the word's slot, the joiner and the act on one row — ${paneHead}`);
  } finally { WRITE.setKept(D, was.kept); REC.setSession(was.session); }
}));

test('a change of the head\'s rows changes the band its fold reserves, and the article set again re-anchors the camera on the passage being read: its line at its height and its size (issue #436; FP-8)', () => onLayer(() => {
  deliver();
  REC.takeMetadata(D, { doc: D, published: true, owner: '1.0.1', birth: D + '.1', birthExtent: EXTENT, placed: null, baseExtent: null, source: null, asOf: 1 });
  // a link to D as a whole: its count on the head's first row beside the state's glyph
  const W1 = OTHER_HOME + '.0.2.900';
  REC.takeLinks(D, [W1]);
  REC.takeLink({ addr: W1, from: [span(OTHER_HOME, 1, 1)], to: [whole(D)], type: CITE });
  CAM.setViewport(320, 900);
  assert.ok(CAM.fit().head, '320 px: the corner at the head');
  const box = docBox(D), f0 = LAYER.foldOf(REC.doc(D)), c = f0.columns[0];
  CAM.set({ x: box.x + c.x + c.w / 2, y: box.y + c.y + c.h * 0.4, scale: 17 / f0.fs });
  LAYER.frame();
  const pos = /** @type {number} */ (LAYER.posAt(D, CAM.cam.x, CAM.cam.y));
  const line = () => { const p = placeOf(LAYER.foldOf(REC.doc(D)), pos); return CAM.sy(box.y + p.y); };
  const y = line(), em = CAM.cam.scale * f0.fs;
  // the chain counted: the version statement joins the corner's items before the count, which the head's first row no longer holds
  REC.takeMembers(D, 3);
  const f = LAYER.foldOf(REC.doc(D));
  assert.ok(f.band > f0.band, `the band deeper: ${f0.band} → ${f.band}`);
  LAYER.frame();
  assert.ok(Math.abs(line() - y) < 1e-6, `the passage's line at its height: ${y} → ${line()}`);
  assert.ok(Math.abs(CAM.cam.scale * f.fs - em) < 1e-9, 'at its size on screen');
}, 320, 900));

/** the one line's bottom the layer's readers give, as a test sets it: one row of the line, then three */
const lineAt = { top: 25 };
/** the readers with the one line's bottom at `lineAt.top` */
const rowsOfLine = () => LAYER.readers({ selection: () => null, focus: () => null, top: () => lineAt.top, handOff: () => {}, navigated: () => null });
/** a world height's distance from the visible view's centre, on screen, with the camera at a view and the one line's bottom at `top` */
const fromCentre = (/** @type {number} */ y, /** @type {{y: number, scale: number}} */ view, /** @type {number} */ top) => (y - view.y) * view.scale + VH / 2 - (top + VH) / 2;

test('a view read below one bottom of the one line and returned to below another — the line having taken rows — lands its line at the height it stood from the visible view\'s centre (issue #310; FP-8, FP-25)', () => onLayer(() => {
  lineAt.top = 25;
  rowsOfLine();
  deliver();
  const box = docBox(D), f0 = LAYER.foldOf(REC.doc(D)), c = f0.columns[6];
  CAM.set({ x: box.x + c.x + c.w / 2, y: box.y + c.y + c.h * 0.4, scale: 12 / f0.fs });
  LAYER.frame();
  const view = CAM.view(), r = /** @type {import('./layer.js').Reading} */ (LAYER.readAt(view));
  assert.ok(r && r.addr === D && r.top === 25, 'the view reads D below one row of the line');
  const was = fromCentre(box.y + placeOf(f0, r.pos).y, view, 25);
  lineAt.top = 61;
  const v = /** @type {{x: number, y: number, scale: number}} */ (LAYER.keptAt(view, r, r.pos));
  const now = fromCentre(box.y + placeOf(LAYER.foldOf(REC.doc(D)), r.pos).y, v, 61);
  assert.ok(Math.abs(now - was) < 1e-6 && v.scale === view.scale, `below three rows: the line at the height it stood from the visible centre — ${was} → ${now}`);
}, 1440, 900));

test('an article set again while the one line has taken rows keeps the passage the reader last saw at the visible view\'s centre at its height from that centre as it stands now (issue #310; FP-8)', () => onLayer(() => {
  lineAt.top = 25;
  rowsOfLine();
  deliver();
  const box = docBox(D), f0 = LAYER.foldOf(REC.doc(D)), c = f0.columns[6];
  CAM.set({ x: box.x + c.x + c.w / 2, y: box.y + c.y + c.h * 0.4, scale: 12 / f0.fs });
  LAYER.frame();
  // the passage at the visible centre below one row of the line, and its line's height from that centre
  const centre = CAM.cam.y + 25 / (2 * CAM.cam.scale), pos = /** @type {number} */ (LAYER.posAt(D, CAM.cam.x, centre));
  const was = fromCentre(box.y + placeOf(f0, pos).y, CAM.view(), 25);
  // the line takes two rows more as the article goes stale: a reveal re-breaks it
  lineAt.top = 61;
  LK.reveal(D, 2); LAYER.bump();
  LAYER.frame();
  const f = LAYER.foldOf(REC.doc(D)), now = fromCentre(box.y + placeOf(f, pos).y, CAM.view(), 61);
  assert.ok(placeOf(f, pos).column !== placeOf(f0, pos).column || Math.abs(placeOf(f, pos).y - placeOf(f0, pos).y) > f0.fs, 'the reveal re-breaks the article: the passage moves in its room');
  assert.ok(Math.abs(now - was) < 1e-6, `the passage at the height it stood from the visible centre, below three rows now — ${was} → ${now}`);
  LK.hide(D);
}, 1440, 900));

test('a view read under one fit and returned to under another lands framed across the column its line stands in, at the em it was read at, the line at its height; returned to under the same fit, where it stood (issue #436; FP-8, FP-25)', () => onLayer(() => {
  deliver();
  const box = docBox(D), f0 = LAYER.foldOf(REC.doc(D)), c = f0.columns[6];
  CAM.set({ x: box.x + c.x + c.w / 2 + 40 / (12 / f0.fs), y: box.y + c.y + c.h * 0.4, scale: 12 / f0.fs });
  const view = CAM.view(), r = /** @type {import('./layer.js').Reading} */ (LAYER.readAt(view));
  assert.ok(r && r.addr === D, 'the view reads D');
  assert.deepEqual(LAYER.keptAt(view, r, r.pos), view, 'the same fit: the view where it stood');
  CAM.setViewport(600, 900);
  const v = /** @type {{x: number, y: number, scale: number}} */ (LAYER.keptAt(view, r, r.pos)), f = LAYER.foldOf(REC.doc(D)), em = view.scale * f0.fs;
  assert.ok(f.cpl < MEASURE_CPL && Math.abs(v.scale * f.fs - em) < 1e-9, `600 px: a narrower measure, the em it was read at — ${v.scale * f.fs}`);
  assert.ok(Math.abs(v.x - LAYER.frameOf(D, r.pos, em).x) < 1e-6, 'its centre framed across the line\'s column');
  const p0 = placeOf(f0, r.pos), p = placeOf(f, r.pos);
  assert.ok(Math.abs((box.y + p.y - v.y) * v.scale - (box.y + p0.y - view.y) * view.scale) < 1e-6, 'the line at its height from the view\'s centre');
}, 1440, 900));

// ---- each draft's last caret, holding its place by its bytes (B3-S1 P59, P60) ----------------------------------------

/** the two lines `twoDrafts` delivers in each draft, and the second draft */
const DRAFTED = 'First line.\n\nSecond line here.\n', TWIN = '1.0.1.0.5';
/** D and TWIN listed as drafts of the session's account, each holding DRAFTED, every byte named through its image, the camera at their reading scale: DRAFTED's length */
function twoDrafts() {
  const n = byteLength(DRAFTED);
  REC.takeIndex(/** @type {any} */ ({ docs: [D, TWIN].map((doc) => ({ doc, kind: 'draft', label: null, standing: 'yours_to_read' })), counts: [{ account: '1.0.1', documents: 2 }], state: { arm: 'complete' } }));
  for (const a of [D, TWIN]) {
    REC.takeSpanSet(a, [{ subspace: 1, ordinal: 1, positions: n }]);
    REC.takeDelivery(a, [{ pos: 1, width: n, kind: 'content', text: DRAFTED, ref: null, origin: null }], 7, { from: 1, runs: [{ iStart: a + '.0.1.1', width: n }] });
  }
  CAM._reset(); CAM.setViewport(1440, 900);
  const f = LAYER.foldOf(REC.doc(D)), box = docBox(D), c = f.columns[0];
  CAM.set({ x: box.x + c.x + c.w / 2, y: box.y + c.y + c.h / 2, scale: 12 / f.fs });
  return n;
}

test('each draft keeps its last caret for the session: a caret placed in another draft leaves the first kept there — read as that draft\'s by caretIn, caretInSpan and caretSpan, marked while the walk\'s focus holds its span, Enter at that span returning it and at another placing one in its place — and a change of the page\'s class drops every draft\'s caret but the page\'s own (B3-S1 P59; D5 M-11; D6 BM-52)', () => {
  twoDrafts();
  try {
    assert.deepEqual([LAYER.editable(D), LAYER.editable(TWIN)], [true, true], 'two drafts the person may edit');
    LAYER.placeCaret(D, 16); LAYER.caretType('x');
    LAYER.placeCaret(TWIN, 3);
    assert.deepEqual([LAYER.caret(), LAYER.caretIn(D), LAYER.caretIn(TWIN)], [{ addr: TWIN, pos: 3, live: true }, { addr: D, pos: 17, live: false }, { addr: TWIN, pos: 3, live: true }], 'the page\'s caret placed in the twin: D keeps its own, kept where it stood');
    assert.deepEqual([LAYER.caretInSpan(D, 14), LAYER.caretInSpan(D, 1), LAYER.caretInSpan(TWIN, 1), LAYER.caretSpan(D), LAYER.caretSpan()], [true, false, true, { addr: D, pos: 17, block: 14 }, { addr: TWIN, pos: 3, block: 1 }], 'each draft\'s caret in its own span');
    LAYER.readers({ focus: () => ({ addr: D, pos: 14 }) });
    assert.deepEqual(LAYER.caretsMarked(), [{ addr: D, pos: 17, live: false }, { addr: TWIN, pos: 3, live: true }], 'the walk\'s focus on the span D\'s caret stands in: that caret marked, kept, beside the page\'s own');
    LAYER.readers({ focus: () => ({ addr: D, pos: 1 }) });
    assert.deepEqual(LAYER.caretsMarked(), [{ addr: TWIN, pos: 3, live: true }], 'the walk\'s focus on another span of D: the page\'s own alone');
    assert.deepEqual(LAYER.caretToSpan(D, 14), { addr: D, pos: 17, live: true }, 'Enter at the span D\'s caret stands in: returned where it stood');
    assert.deepEqual(LAYER.caretIn(TWIN), { addr: TWIN, pos: 3, live: false }, 'the twin keeping its own, kept');
    assert.deepEqual(LAYER.caretToSpan(TWIN, 14), { addr: TWIN, pos: 14, live: true }, 'Enter at another span of the twin: a caret placed there');
    assert.deepEqual([LAYER.caretIn(TWIN), LAYER.caretIn(D)], [{ addr: TWIN, pos: 14, live: true }, { addr: D, pos: 17, live: false }], 'the twin\'s caret replaced, D\'s standing');
    REC.sessionDied({ arm: 'closed' });
    assert.deepEqual([LAYER.caretIn(D), LAYER.caret()], [null, { addr: TWIN, pos: 14, live: true }], 'a change of the page\'s class: D\'s caret dropped, the page\'s own standing');
  } finally { LAYER.dropCaret(); LAYER.readers({}); WRITE.clearEdits(D); CAM._reset(); }
});

test('a caret holds its place by the bytes either side of it: words another writer set above it, read again with their image, move it on with them — the page\'s own caret and a draft\'s kept one alike — an edit made at no caret moves it too, and a text set again before its image holds it at its position until the image places its bytes; a trail entry holds it by its place, and a return restores it there kept (B3-S1 (iii), P60; FP-38)', () => {
  const n = twoDrafts();
  /** D set again in one step as a feed row's reads set it: its text, and the image read with it, or none */
  const setD = (/** @type {string} */ text, /** @type {Array<{iStart: string, width: number}> | null} */ image) => {
    const w = byteLength(text);
    REC.setAgain(D, { spans: [{ subspace: 1, ordinal: 1, positions: w }], text: { runs: [{ pos: 1, width: w, kind: 'content', text, ref: null, origin: null }], asOf: 9 }, ...(image ? { image: { from: 1, runs: image } } : {}) });
  };
  const lead = 'Set above.\n\n', k = byteLength(lead), more = 'Another line.\n\n', m = byteLength(more);
  try {
    LAYER.placeCaret(D, 16); LAYER.leaveCaret('esc');
    const left = /** @type {import('./layer.js').CaretPlace} */ (LAYER.caretPlace());
    assert.deepEqual(left, { addr: D, pos: 16, before: [{ prefix: D + '.0.1', ordinal: 15, width: 1 }], after: [{ prefix: D + '.0.1', ordinal: 16, width: 1 }] }, 'the caret by its place: its position and the bytes either side of it');
    setD(lead + DRAFTED, [{ iStart: `${D}.0.1.${n + 1}`, width: k }, { iStart: D + '.0.1.1', width: n }]);
    assert.deepEqual(LAYER.caret(), { addr: D, pos: 16 + k, live: false }, 'a line another writer set above the kept caret, read again: the caret on the same characters');
    WRITE.addEdit(D, { pos: 1, width: 0, text: 'ab' });
    assert.equal(LAYER.caret()?.pos, 18 + k, 'an edit made at no caret above it: moved on with its bytes');
    WRITE.clearEdits(D);
    assert.equal(LAYER.caret()?.pos, 16 + k, 'that edit gone: back with them');
    setD(more + lead + DRAFTED, null);
    assert.equal(LAYER.caret()?.pos, 16 + k, 'set again before its image: held at its position');
    REC.takeImage(D, 1, [{ iStart: `${D}.0.1.${n + k + 1}`, width: m }, { iStart: `${D}.0.1.${n + 1}`, width: k }, { iStart: D + '.0.1.1', width: n }]);
    assert.equal(LAYER.caret()?.pos, 16 + k + m, 'its image arrived: on the same characters again');
    LAYER.placeCaret(TWIN, 1);
    setD(lead + more + lead + DRAFTED, [{ iStart: `${D}.0.1.${n + k + m + 1}`, width: k }, { iStart: `${D}.0.1.${n + k + 1}`, width: m }, { iStart: `${D}.0.1.${n + 1}`, width: k }, { iStart: D + '.0.1.1', width: n }]);
    assert.deepEqual(LAYER.caretIn(D), { addr: D, pos: 16 + 2 * k + m, live: false }, 'D\'s kept caret, the page\'s own in the twin: held by its bytes the same way');
    assert.deepEqual([LAYER.restoreCaret(left), LAYER.caretIn(TWIN)], [{ addr: D, pos: 16 + 2 * k + m, live: false }, { addr: TWIN, pos: 1, live: false }], 'a return restoring the place an entry held: kept where its bytes stand now, the page\'s own, the twin keeping its caret kept');
    assert.equal(LAYER.caretOwes(), null, 'and the frame owes it nothing: no camera moves for it');
  } finally { LAYER.dropCaret(); WRITE.clearEdits(D); CAM._reset(); }
});

// ---- the caret's paste and cut, on a page of the DOM under `web/test/` ------------------------------------------------

/** the lines the draft of `onDraft` holds: "words" at 9, "stand" at 15, the second line from 28 */
const WORDS = 'Tumbler words stand here.\n\nThe second line holds more words.\n';
/** the board's origin a cut's entry names in `onDraft` */
const ORIGIN = 'http://board.test';
/** every answer the fake port owes run */
const flush = async () => { for (let i = 0; i < 6; i++) await new Promise((r) => setImmediate(r)); };

/**
 * A cut event as the platform delivers it, over a clipboard of the test's own: the event, the flavors set on that
 * clipboard, by name, and whether its default was prevented; `none` for an event carrying no clipboard.
 */
function cutEvent(none = false) {
  /** @type {Record<string, string>} */
  const set = {};
  let prevented = false;
  return { e: { clipboardData: none ? null : { setData: (/** @type {string} */ k, /** @type {string} */ v) => { set[k] = v; } }, preventDefault() { prevented = true; } }, set, prevented: () => prevented };
}

/**
 * @typedef {Object} Drafted — what `onDraft` hands a test
 * @property {string} P the draft
 * @property {Array<Record<string, any>>} frames every write frame the page dialed, in order
 * @property {() => Array<[number, number, string]>} edits the draft's page-local edits: each its position, the width it replaced and its text
 * @property {() => ([string, number, boolean] | null)} caret the caret as it stands: its document, its position and whether it is live
 * @property {() => string} shown the text the page shows of the draft
 * @property {() => Array<[string, boolean]>} steps the draft's undo stack: each step's kind and whether its run is open
 * @property {ReturnType<typeof page>} dom the page's DOM
 */

/**
 * The test run on a page of the DOM under `web/test/`: one draft of the session's account holding `WORDS`, read at
 * position 7 with its image, mounted as the layer mounts it at its reading scale; the session one that writes, and D6's
 * machine handed in over a fake port acking every write frame `writes` gives no answer to, an insert's bytes minted, and
 * answering a read only as `reads` answers it. Every caret, edit and article is let go after it.
 * @param {(d: Drafted) => Promise<void>} body
 * @param {(frame: Record<string, any>) => unknown} [reads] the answer to a read frame; none, the fake's own refusal, where it gives none
 * @param {(frame: Record<string, any>) => unknown} [writes] the answer to a write frame; the fake's ack where it gives none
 */
async function onDraft(body, reads = () => undefined, writes = () => undefined) {
  const dom = page({ width: 1440, height: 900 }), P = '1.0.1.0.2', n = byteLength(WORDS);
  dom.install();
  try {
    MACHINE._reset(); REC._reset(); WRITE._reset();
    /** @type {Array<Record<string, any>>} */
    const frames = [];
    let k = 0;
    const fake = FAKE.create(new Proxy({}, {
      get: (_t, key) => {
        if (String(key).startsWith('held:')) return { result: [] };
        if (!String(key).startsWith('op:')) return undefined;
        const frame = JSON.parse(String(key).slice(3));
        // a read the pump makes of the draft it wrote in is no write: answered only where the test answers it
        if (frame.frame || F.READ_OPS.includes(frame.op)) return reads(frame);
        frames.push(frame);
        return writes(frame) ?? { result: frame.op === 'insert' ? { addr: `${P}.0.1.${1000 * ++k}`, at: 20 + k, resp: 'ack_addr' } : { at: 20 + ++k, resp: 'ack' } };
      },
    }));
    PORT.boot(fake);
    REC.setBoard({ board: 'b-1', name: '', origin: ORIGIN });
    REC.setSession(/** @type {any} */ ({ session: 's-1', principal: 1, account: '1.0.1', writes: true, fingerprint: null }));
    REC.takeIndex(/** @type {any} */ ({ docs: [{ doc: P, kind: 'draft', label: null, standing: 'yours_to_read' }], counts: [{ account: '1.0.1', documents: 1 }], state: { arm: 'complete' } }));
    REC.takeSpanSet(P, [{ subspace: 1, ordinal: 1, positions: n }]);
    REC.takeDelivery(P, [{ pos: 1, width: n, kind: 'content', text: WORDS, ref: null, origin: null }], 7, { from: 1, runs: [{ iStart: P + '.0.1.1', width: n }] });
    MACHINE.handIn();
    CAM.setViewport(1440, 900);
    const f = LAYER.foldOf(REC.doc(P)), box = docBox(P), c = f.columns[0];
    CAM.set({ x: box.x + c.x + c.w / 2, y: box.y + c.y + c.h / 2, scale: 12 / f.fs });
    const layer = dom.element('div');
    layer.id = 'domlayer'; layer.clientWidth = 1440; layer.clientHeight = 900;
    dom.document.body.appendChild(layer);
    LAYER.attach(/** @type {any} */ (layer), /** @type {any} */ (null));
    LAYER.frame();
    assert.deepEqual([LAYER.isMounted(P), LAYER.editable(P)], [true, true], 'the draft stands as text the person may edit');
    await body({
      P, frames, dom,
      edits: () => WRITE.edits(P).map((e) => [e.pos, e.width, e.text]),
      caret: () => { const x = LAYER.caret(); return x && [x.addr, x.pos, x.live]; },
      shown: () => { const d = LAYER.shownOf(P); return d.from < 0 ? '' : REC.textOf(d.runs, d.from, d.to); },
      steps: () => WRITE.undoOf(P).map((x) => [x.kind, x.open]),
    });
  } finally {
    LAYER.dropCaret(); LAYER.clear(); readers(null);
    MACHINE._reset(); REC._reset(); WRITE._reset(); PORT.boot(null);
    dom.uninstall();
  }
}

test('text pasted at a live caret is one page-local edit, a step of its own, the caret after it — each CR LF and lone CR a line feed, as a typed Enter\'s; a selection whole in the caret\'s text is replaced by it in the one edit, and one of another document, or reaching past the text shown, is left and the text placed at the caret (D5 K-93; B3-S5 (ii); D6 BM-31)', () => onDraft(async ({ P, edits, caret, shown, steps }) => {
  LAYER.placeCaret(P, 9);
  assert.equal(LAYER.caretPaste('new '), 'placed');
  assert.deepEqual([edits(), caret(), steps(), shown().slice(0, 18)], [[[9, 0, 'new ']], [P, 13, true], [['paste', false]], 'Tumbler new words '], 'one edit at the caret, the caret after the placed text, one step that is no run of typing');
  assert.equal(LAYER.caretPaste('a\r\nb\rc\n'), 'placed');
  assert.deepEqual([edits().at(-1), caret(), steps()], [[13, 0, 'a\nb\nc\n'], [P, 19, true], [['paste', false], ['paste', false]]], 'CR LF and a lone CR each a line feed, the caret past the six bytes placed; a second paste a second step');
  WRITE.clearEdits(P);
  // "words stand" selected, the caret at its end
  LAYER.placeCaret(P, 20);
  assert.equal(LAYER.caretPaste('XY', { addr: P, pos: 9, width: 11 }), 'placed');
  assert.deepEqual([edits(), caret(), shown().slice(0, 16)], [[[9, 11, 'XY']], [P, 11, true], 'Tumbler XY here.'], 'over a selection: its bytes out and the text in their place, one edit, the caret after the text');
  WRITE.clearEdits(P);
  LAYER.placeCaret(P, 9);
  const n = byteLength(WORDS);
  for (const [what, over] of /** @type {Array<[string, import('./span.js').Span]>} */ ([['a selection of another document', { addr: '1.0.1.0.3', pos: 1, width: 4 }], ['a selection reaching past the text shown', { addr: P, pos: n - 2, width: 10 }]])) {
    assert.equal(LAYER.caretPaste('Q', over), 'placed');
    assert.deepEqual([edits().at(-1), caret()?.[1]], [[9, 0, 'Q'], 10], `${what}: left, the text placed at the caret`);
    WRITE.clearEdits(P);
    LAYER.placeCaret(P, 9);
  }
}));

/** skep's own entry as a copy writes it, of bytes by identity on the fixture's board, each part's length in the plain text given */
const entryOf = (/** @type {string} */ doc, /** @type {Array<Record<string, unknown>>} */ ids, /** @type {number[] | null} */ lengths) => JSON.stringify({ board: ORIGIN, doc, member: null, plain: false, pos: null, width: null, ids, version: 2, lengths });

test('B3-S5 (i), C3: a paste whose skep entry names this board\'s bytes, their words at hand, places the same words by their identity — one act, a removal kept for them and the put-back naming it, the caret after them — where those words, read as a copy reads them, are the plain text\'s; and places the plain text as new bytes, saying so where it was made, where they differ at the same lengths, or where the lengths do not cut the plain text (the paste survey\'s C2, O6); another board\'s entry places the plain text, saying nothing', () => onDraft(async ({ P, edits, caret, shown, steps }) => {
  const words = entryOf(P, [{ prefix: P + '.0.1', ordinal: 9, width: 5 }], [5]);
  LAYER.placeCaret(P, 26);
  assert.equal(LAYER.caretPaste('words', null, words), 'same');
  assert.deepEqual([shown().slice(0, 31), caret(), steps(), WRITE.edits(P).map((e) => [e.pos, e.width, !!e.based, e.back ? e.back.width : null])], ['Tumbler words stand here.words\n', [P, 31, true], [['paste', false]], [[26, 0, true, null], [26, 0, false, 5]]],
    'the same bytes placed at the caret by identity, the caret after them, one step');
  assert.deepEqual(REC.identityIn(LAYER.shownOf(P).image, 26, 5), [{ prefix: P + '.0.1', ordinal: 9, width: 5 }], 'by the identity the entry named: standing twice in the draft');
  WRITE.clearEdits(P);
  LAYER.placeCaret(P, 26);
  const site = { before: [{ prefix: P + '.0.1', ordinal: 25, width: 1 }], after: [{ prefix: P + '.0.1', ordinal: 26, width: 1 }] };
  assert.deepEqual(LAYER.caretPaste('wordz', null, words), { told: 'differs', name: 'differs', doc: P, site }, 'the same lengths, other words: told, where the paste was made');
  assert.deepEqual([edits(), caret()], [[[26, 0, 'wordz']], [P, 31, true]], 'the plain text placed as new bytes, one edit — never the bytes the entry named');
  WRITE.clearEdits(P);
  LAYER.placeCaret(P, 26);
  assert.deepEqual(LAYER.caretPaste('words!', null, words), { told: 'differs', name: 'differs', doc: P, site }, 'lengths that do not cut the plain text: told the same way');
  assert.deepEqual(edits(), [[26, 0, 'words!']], 'new bytes');
  WRITE.clearEdits(P);
  LAYER.placeCaret(P, 26);
  assert.equal(LAYER.caretPaste('words', null, JSON.stringify({ ...JSON.parse(words), board: 'http://elsewhere' })), 'placed', 'another board\'s entry: the plain text, nothing said');
  assert.deepEqual(edits(), [[26, 0, 'words']]);
}));

test('a byte the text holds twice names no caret\'s place: after the draft\'s own words pasted by their identity, the caret is held by the byte after it alone, so the board refusing the paste\'s source takes the words back out and leaves the caret where the paste was made — never after the words they were copied from (FP-38; B3-S5; the paste survey\'s W3)', () => onDraft(async ({ P, frames, edits, caret, shown }) => {
  const words = entryOf(P, [{ prefix: P + '.0.1', ordinal: 9, width: 5 }], [5]);
  LAYER.placeCaret(P, 26);
  assert.equal(LAYER.caretPaste('words', null, words), 'same');
  assert.deepEqual([shown().slice(0, 30), LAYER.caretPlace()], ['Tumbler words stand here.words', { addr: P, pos: 31, before: [], after: [{ prefix: P + '.0.1', ordinal: 26, width: 1 }] }],
    'the same bytes standing twice, the caret after them held by the byte after it: the one before it stands twice');
  await flush();
  assert.deepEqual([frames.map((f) => f.op), edits(), shown().slice(0, 26), caret()], [['reinstate'], [], 'Tumbler words stand here.\n', [P, 26, true]],
    'its `reinstate` refused `withheld`: nothing placed, the text as it stood, the caret live where the paste was made');
}, undefined, (frame) => (frame.op === 'reinstate' ? { refused: { kind: 'refused', name: 'withheld', status: 200, code: 'withheld', detail: null, op: 'reinstate', site: { addr: '1.0.1.0.2' }, body: null } } : undefined)));

test('B3-S5 (i), W5: a paste whose entry names bytes no record at hand holds reads them by identity first — `retrieve_i` of their spans — and waits on it: their words read back as the plain text\'s, the same words are placed where the paste was made; a read refused `withheld` names the origin, `doc_not_registered` the source the board says nothing of, a position the document minted nothing at is the page\'s own fault, a read never answered is said so, and a draft changed at the paste\'s place while it was read is said so — each placing nothing', async () => {
  const S = '1.0.1.0.88', at = (/** @type {number} */ n) => `${S}.0.1.${n}`;
  /** @type {string[]} */
  const asked = [];
  let answer = (/** @type {Record<string, any>} */ _frame) => /** @type {unknown} */ (undefined);
  const reads = (/** @type {Record<string, any>} */ frame) => { if (frame.op !== 'retrieve_i') return undefined; asked.push(frame.spans.map((/** @type {{start: string, width: string}} */ x) => `${x.start}+${x.width}`).join(' ')); return answer(frame); };
  const delivered = (/** @type {Array<Record<string, unknown> | null>} */ values) => ({ result: { as_of: 9, items: values.map((value, i) => ({ at: at(4 + i), value })), resp: 'i_delivery' } });
  const refused = (/** @type {string} */ name, /** @type {Record<string, unknown>} */ site = {}) => ({ refused: { kind: 'refused', name, status: 200, code: name, detail: null, op: 'retrieve_i', site, body: null } });
  const entry = entryOf(S, [{ prefix: S + '.0.1', ordinal: 4, width: 3 }], [3]);
  await onDraft(async ({ P, edits, caret, shown, frames }) => {
    answer = () => delivered([{ content: 'a' }, { content: 'b' }, { content: 'c' }]);
    LAYER.placeCaret(P, 26);
    const out = LAYER.caretPaste('abc', null, entry);
    assert.ok(out instanceof Promise, 'the source not at hand: the paste waits on its read');
    assert.deepEqual([await out, asked, shown().slice(0, 29), caret()], ['same', [`${at(4)}+3`], 'Tumbler words stand here.abc\n', [P, 29, true]], 'read by identity, then placed: the same bytes, the caret after them');
    assert.deepEqual(REC.identityIn(LAYER.shownOf(P).image, 26, 3), [{ prefix: S + '.0.1', ordinal: 4, width: 3 }], 'by the identity read');
    await new Promise((r) => setImmediate(r)); await new Promise((r) => setImmediate(r));
    assert.deepEqual(frames.map((f) => [f.op, f.runs]), [['reinstate', [{ i_start: at(4), origin: S, width: '3' }]]], 'its `reinstate` sent after the read');
    const site = { before: [{ prefix: P + '.0.1', ordinal: 25, width: 1 }], after: [{ prefix: P + '.0.1', ordinal: 26, width: 1 }] };
    for (const [why, give, name, doc] of /** @type {Array<[string, () => unknown, string, string | null]>} */ ([
      ['withheld', () => refused('withheld', { addr: S }), 'withheld', S],
      ['unregistered', () => refused('doc_not_registered'), 'source_not_registered', S],
      ['a position never minted', () => delivered([{ content: 'a' }, null, { content: 'c' }]), 'dangling_source', S],
      ['never answered', () => undefined, 'unread', S],
    ])) {
      WRITE.clearEdits(P);
      LAYER.placeCaret(P, 26);
      answer = give;
      assert.deepEqual([await LAYER.caretPaste('abc', null, entry), edits(), caret()], [{ told: 'unplaced', name, doc, site }, [], [P, 26, true]], `${why}: nothing placed, told`);
    }
    WRITE.clearEdits(P);
    LAYER.placeCaret(P, 26);
    answer = () => delivered([{ content: 'x' }, { content: 'y' }, { content: 'z' }]);
    assert.deepEqual([await LAYER.caretPaste('abc', null, entry), edits()], [{ told: 'differs', name: 'differs', doc: S, site }, [[26, 0, 'abc']]], 'its words read as other words: the plain text placed, told');
    WRITE.clearEdits(P);
    LAYER.placeCaret(P, 26);
    answer = () => { WRITE.addEdit(P, { pos: 25, width: 1, text: '' }); return delivered([{ content: 'a' }, { content: 'b' }, { content: 'c' }]); };
    assert.deepEqual([await LAYER.caretPaste('abc', null, entry), edits()], [{ told: 'unplaced', name: 'moved', doc: null, site }, [[25, 1, '']]], 'the byte before its place taken out while the source was read: nothing placed, told');
  }, reads);
});

test('a paste places nothing where the clipboard held no text, where its text is more than one paste places — counted in UTF-8 bytes once its line endings are set — where no live caret stands, and where the caret\'s draft cannot be written now; the most one paste places is placed whole (B3-S5 (ii); D6 BM-58)', () => onDraft(async ({ P, edits, caret }) => {
  const most = WRITE.PASTE_MAX_BYTES;
  LAYER.placeCaret(P, 9);
  assert.deepEqual([LAYER.caretPaste(''), edits(), caret()], ['none', [], [P, 9, true]], 'no text: nothing placed, the caret where it stood');
  assert.deepEqual([LAYER.caretPaste('é'.repeat(most / 2) + 'a'), edits(), caret()], ['large', [], [P, 9, true]], 'two-byte characters to the most and one byte more: past it by its bytes, never its characters — nothing placed');
  assert.deepEqual([LAYER.caretPaste('a'.repeat(most) + '\n'), edits()], ['large', []], 'one byte past the most: nothing placed');
  assert.deepEqual([LAYER.caretPaste('a'.repeat(most - 1) + '\r\n'), edits().map((e) => [e[0], e[1], byteLength(e[2])]), caret()], ['placed', [[9, 0, most]], [P, 9 + most, true]],
    'the most one paste places, a CR LF its last byte once set: placed whole');
  WRITE.clearEdits(P);
  LAYER.placeCaret(P, 9);
  WRITE.setUnwritable('b-1', { why: 'keyless' });
  assert.deepEqual([LAYER.caretPaste('x'), edits(), caret()], [false, [], [P, 9, true]], 'a draft that cannot be written: nothing placed, the caret not moved past words that are not there');
  WRITE.setUnwritable('b-1', null);
  LAYER.leaveCaret('esc');
  assert.deepEqual([LAYER.caretPaste('x'), edits()], [false, []], 'a kept caret: nothing placed until it is returned');
  LAYER.dropCaret();
  assert.equal(LAYER.caretPaste('x'), false, 'no caret: nothing placed');
}));

test('a cut at a live caret writes the clipboard as a copy of the selection writes it — its plain text, and skep\'s own entry naming the board, the draft and the selection\'s bytes by identity — prevents the platform\'s cut, then takes the bytes out as one edit, a step of its own, the caret at the removal; the removal\'s deletion face is keyed to the `delete` its burst\'s commit sends, never to the act (D5 K-93; B3-S5 (iv); D6 BM-31, BM-51; FP-24, FP-27)', () => onDraft(async ({ P, frames, edits, caret, shown, steps }) => {
  // "words stand" selected, the caret at its end
  const span = { addr: P, pos: 9, width: 11 };
  LAYER.placeCaret(P, 20);
  const c = cutEvent();
  assert.equal(LAYER.caretCut(c.e, span, ORIGIN), 'cut');
  assert.deepEqual(Object.keys(c.set).sort(), ['application/x-skep-passage', 'text/plain'], 'two flavors, and no other');
  assert.deepEqual([c.set['text/plain'], JSON.parse(c.set['application/x-skep-passage']), c.prevented()],
    ['words stand', { board: ORIGIN, doc: P, member: null, plain: false, pos: null, width: null, ids: [{ prefix: P + '.0.1', ordinal: 9, width: 11 }], version: 2, lengths: [11] }, true],
    'the plain text the words cut; the entry the board, the draft — never its positions — the bytes by identity, its version and each part\'s length in the plain text; the platform\'s cut prevented');
  assert.deepEqual([edits(), caret(), shown().slice(0, 14), steps()], [[[9, 11, '']], [P, 9, true], 'Tumbler  here.', [['cut', false]]], 'the bytes out as one edit, the caret at the removal, one step that is no run of typing');
  assert.deepEqual([frames, WRITE.removalsOf(P)], [[], []], 'nothing dialed at the act, and no removal faced there');
  WRITE.commit(P);
  await flush();
  assert.deepEqual([frames.map((x) => [x.op, x.p, x.width]), WRITE.removalsOf(P).map((r) => r.words)], [[['delete', { ordinal: '9', subspace: '1' }, '11']], ['words stand']],
    'the commit sends one `delete`, and the removal its face stands at is made with it');
}));

test('a cut the clipboard cannot take whole writes nothing and removes nothing: a selection reaching past the text shown, one of no width, an event carrying no clipboard, and a span the platform\'s selection cannot be placed over while another selection stands — what is copied is what is cut; a selection of another document, a kept caret and a draft that cannot be written cut nothing either (B3-S5 (iv); D6 BM-58; FP-20)', () => onDraft(async ({ P, edits, caret, dom }) => {
  const n = byteLength(WORDS), span = { addr: P, pos: 9, width: 11 };
  LAYER.placeCaret(P, 20);
  // a field the reader types in holds the focus, so no range is placed over the span, and the platform's selection stands over "Tumbler"
  const other = /** @type {Range} */ (LAYER.rangeOf({ addr: P, pos: 1, width: 7 })), field = dom.element('input');
  dom.document.selection.addRange(/** @type {any} */ (other));
  dom.document.activeElement = field;
  const elsewhere = cutEvent();
  assert.deepEqual([LAYER.caretCut(elsewhere.e, span, ORIGIN), elsewhere.set, elsewhere.prevented(), edits(), LAYER.spanOfSelection()], ['uncopied', {}, false, [], { addr: P, pos: 1, width: 7 }],
    'the platform\'s selection standing over other words than the span: nothing written — never those other words — and nothing removed');
  dom.document.activeElement = null;
  dom.document.selection.removeAllRanges();
  for (const [what, over, none] of /** @type {Array<[string, import('./span.js').Span, boolean]>} */ ([['a selection reaching past the text shown', { addr: P, pos: n - 2, width: 10 }, false], ['a selection of no width', { addr: P, pos: 9, width: 0 }, false], ['an event carrying no clipboard', span, true]])) {
    const c = cutEvent(none);
    assert.deepEqual([LAYER.caretCut(c.e, over, ORIGIN), c.set, c.prevented(), edits(), caret()], ['uncopied', {}, false, [], [P, 20, true]], `${what}: nothing written, nothing removed, the caret where it stood`);
  }
  /** a cut of "words stand" made now: what it answered, what it set, and the edits after it */
  const cut = (/** @type {import('./span.js').Span} */ over = span) => { const c = cutEvent(); return [LAYER.caretCut(c.e, over, ORIGIN), c.set, edits()]; };
  assert.deepEqual(cut({ addr: '1.0.1.0.3', pos: 9, width: 11 }), [false, {}, []], 'a selection of another document: nothing cut');
  WRITE.setUnwritable('b-1', { why: 'keyless' });
  assert.deepEqual(cut(), [false, {}, []], 'a draft that cannot be written: the clipboard untouched, nothing removed');
  WRITE.setUnwritable('b-1', null);
  LAYER.leaveCaret('esc');
  assert.deepEqual(cut(), [false, {}, []], 'a kept caret: nothing cut until it is returned');
}));

test('words still in their open burst carry no face when cut: typed and cut before any commit, they are named on the clipboard by the page\'s own name of their bytes, and the burst\'s commit sends nothing for them and makes no removal the deletion face stands at (D6 BM-1, BM-51; FP-38)', () => onDraft(async ({ P, frames, edits, shown }) => {
  LAYER.placeCaret(P, 1);
  for (const ch of 'abc ') LAYER.caretType(ch);
  LAYER.frame();
  assert.deepEqual([shown().slice(0, 11), WRITE.inFlight(P), frames], ['abc Tumbler', true, []], 'four keys typed, their burst open, nothing dialed');
  const c = cutEvent();
  assert.equal(LAYER.caretCut(c.e, { addr: P, pos: 1, width: 4 }, ORIGIN), 'cut');
  assert.deepEqual([c.set['text/plain'], JSON.parse(c.set['application/x-skep-passage']).ids, shown().slice(0, 7)], ['abc ', [{ prefix: REC.pageSpace(P), ordinal: 1, width: 4, load: REC.PAGE_LOAD }], 'Tumbler'],
    'cut: the clipboard holds their text, the entry naming them by the page\'s own name and its load, and they are out of the text');
  WRITE.commit(P);
  await flush();
  assert.deepEqual([frames, WRITE.removalsOf(P), WRITE.inFlight(P), WRITE.keptOf(P)?.word], [[], [], false, 'kept'], 'the commit sends nothing for them and makes no removal: the burst changes nothing on the board, and the corner reads "kept"');
}));

/** a reading scene's pane's article of `onDraft`'s draft, T-LAYER's mount (`sceneArticle`), standing in the page beside the plane's, which mounts the same draft */
function paneArticle(/** @type {ReturnType<typeof page>} */ dom, /** @type {string} */ P, /** @type {{names?: string, shows?: string}} */ as = {}) {
  const el = LAYER.sceneArticle(REC.doc(P), as);
  dom.document.body.appendChild(/** @type {any} */ (el));
  return el;
}

test('a reading scene\'s pane\'s selection is placed in that pane\'s article, though the plane mounts the same document: its anchor at its end where asked, one already reading the span there left as it stands, its anchor where it was set, and nothing placed while a field holds the focus — the plane\'s article holding none of it (issue #94; FP-10, FP-20)', () => onDraft(async ({ P, dom }) => {
  const pane = paneArticle(dom, P), s = dom.document.selection, plane = /** @type {any} */ (LAYER.mountedSet().get(P)).el;
  const span = { addr: P, pos: 9, width: 5 }, back = { addr: P, pos: 15, width: 5 };
  LAYER.placeSelection(span, null, { el: pane, backward: false });
  assert.deepEqual([LAYER.selectionIn(pane), LAYER.selectionIn(plane), LAYER.spanOfSelection()], [{ span, backward: false }, null, null], 'placed in the pane\'s article, none of it in the plane\'s');
  LAYER.placeSelection(back, null, { el: pane, backward: true });
  assert.deepEqual(LAYER.selectionIn(pane), { span: back, backward: true }, 'its anchor at its end where asked');
  LAYER.placeSelection(back, null, { el: pane, backward: false });
  assert.deepEqual(LAYER.selectionIn(pane), { span: back, backward: true }, 'one reading the span there stands as it is, its anchor where it was set');
  s.removeAllRanges();
  dom.document.activeElement = dom.element('input');
  LAYER.placeSelection(span, null, { el: pane, backward: false });
  assert.equal(s.rangeCount, 0, 'nothing placed while a field holds the focus');
  dom.document.activeElement = null;
}));

test('a span\'s rects at a reading scene\'s pane are read from that pane\'s article, never the plane\'s that mounts the same document, and at the plane from the plane\'s; none where the pane\'s article is made as another address (issue #94)', () => onDraft(async ({ P, dom }) => {
  const pane = paneArticle(dom, P), make = dom.document.createRange.bind(dom.document);
  // each range laid out where the article holding it stands: the pane's at x 500, the plane's at x 100
  dom.document.createRange = () => { const r = make(); /** @type {any} */ (r).getClientRects = () => [{ left: pane.contains(/** @type {any} */ (r.startContainer)) ? 500 : 100, top: 40, width: 30, height: 12 }]; return r; };
  assert.deepEqual(LAYER.spanRects(P, 9, 5, pane), [{ x: 500, y: 40, w: 30, h: 12 }], 'at the pane: the pane\'s article\'s');
  assert.deepEqual(LAYER.spanRects(P, 9, 5), [{ x: 100, y: 40, w: 30, h: 12 }], 'at the plane: the plane\'s');
  assert.equal(LAYER.spanRects('1.0.1.0.157', 9, 5, pane), null, 'another address than the pane\'s article is made as: none');
}));

test('the span a range covers is read with its site — the plane where the plane\'s mounted article holds it, else the reading scene\'s pane\'s article holding it whole — and `spanOfRange`, the plane\'s alone, answers none of a pane\'s (issue #94)', () => onDraft(async ({ P, dom }) => {
  const pane = paneArticle(dom, P), span = { addr: P, pos: 9, width: 5 };
  const inPane = /** @type {Range} */ (LAYER.rangeIn(pane, span)), onPlane = /** @type {Range} */ (LAYER.rangeOf(span));
  const pSited = LAYER.siteOfRange(inPane), qSited = LAYER.siteOfRange(onPlane);
  assert.deepEqual([pSited?.site === pane, pSited?.span, LAYER.spanOfRange(inPane)], [true, span, null], 'in the pane: its site the pane\'s article, its span there; the plane\'s none');
  assert.deepEqual(qSited, { site: 'plane', span }, 'on the plane: the plane\'s');
  dom.document.selection.addRange(/** @type {any} */ (inPane));
  const sited = LAYER.siteOfSelection();
  assert.deepEqual([sited?.site === pane, sited?.span, LAYER.spanOfSelection()], [true, span, null], 'the platform\'s selection read so');
  dom.document.selection.removeAllRanges();
}));

test('a reading scene\'s pane\'s article is marked by its own pane\'s selection alone, never the plane\'s: made with nothing marked while the plane\'s stands over the same words, then each block its pane\'s selection touches marked in place by position — whatever address its head shows — and unmarked as it ends (issue #94; Q6)', () => onDraft(async ({ P, dom }) => {
  readers({ addr: P, pos: 1, width: 30 });
  const pane = paneArticle(dom, P, { names: P + '.7', shows: P });
  const marked = () => [.../** @type {any} */ (pane).querySelectorAll('.run > .sp.sel')].map((e) => Number(e.dataset.pos));
  const blocks = REC.doc(P).blocks, touched = (/** @type {{pos: number, width: number}} */ s) => blocks.filter((b) => b.pos < s.pos + s.width && s.pos < b.pos + b.width).map((b) => b.pos);
  assert.deepEqual(marked(), [], 'the plane\'s selection over the same words marks nothing in the pane');
  LAYER.markPaneSelection(pane, { pos: 9, width: 5 });
  assert.deepEqual(marked(), [1], 'the pane\'s own selection marks the block it touches, though the pane names a member its head does not show');
  LAYER.markPaneSelection(pane, { pos: 20, width: 15 });
  assert.deepEqual(marked(), touched({ pos: 20, width: 15 }).filter((p) => pane.querySelector(`.run > .sp[data-pos="${p}"]`)), 'each block it touches, in place');
  LAYER.markPaneSelection(pane, null);
  assert.deepEqual(marked(), [], 'its end unmarks them');
}));
